	input button, 
	input reset, 
	input set, 
	input [3:0] input_value, 

	output[6:0] displayed_value, 
	output[3:0] output_value 


	);function [6:0] map;
	input integer number;

	case (number)
		0: map = 7'b1000000;
		1: map = 7'b1111001;
		2: map = 7'b0100100;
		3: map = 7'b0110000;
		4: map = 7'b0011001;
		5: map = 7'b0010010;
		6: map = 7'b0000010;
		7: map = 7'b1111000;
		8: map = 7'b0000000;
		9: map = 7'b0010000;
	endcase

endfunction



integer number = 0;
