assign displayed_value[6:0] = map(number);




always @(negedge button or posedge reset or posedge set) 
begin
	if (reset == 1)
		number <= 0;
	else if(set == 1)
		number <= input_value[3:0];

	else
		number <= (number + 1)%10;
end



endmodule

