  if (WIDTH == 2) begin 
  LUT4 #(.lut_function({4{LUT}})) _TECHMAP_REPLACE_ (.dout(Y), .din0(A[0]), .din1(A[1]), .din2(1'b0),.din3(1'b0)); 
  end else 
  if(WIDTH == 3) begin 
