description:
Design a circuit that splits a 7-bit input number (`NUMBER`) into two 4-bit outputs (`A` and `B`). The output `A` represents the tens place of the input number, where `A` is set to values 0 through 5 for input numbers ranging from 0 to 59. The output `B` is the remainder value from `NUMBER` after subtracting the appropriate multiple of ten based on the value of `A`. If the input exceeds 59, both outputs `A` and `B` are set to zero. This module essentially serves as a simple encoder for the range 0-59, effectively converting a single number into its tens and units components.
module top_module(
NUMBER,A,B);

code:
module top_module(
NUMBER,A,B);input [6:0] NUMBER;
output [3:0]A,B;

reg [3:0]A,B;

always @(NUMBER)
begin
	if(NUMBER <=9)
		begin
			A=0;
			B=NUMBER[3:0];
		end
	else if(NUMBER <=19)
		begin
			A=1;
			B=NUMBER -10;
		end
	else if(NUMBER <=29)
		begin
			A=2;
			B=NUMBER -20;
		end
	else if(NUMBER <=39)
		begin
			A=3;
			B=NUMBER -30;
		end		
	else if(NUMBER <=49)
		begin
			A=4;
			B=NUMBER -40;
		end		
	else if(NUMBER <=59)
		begin
			A=5;
			B=NUMBER -50;
		end		
	else 
		begin
			A=0;
			B=0;
		end
end

endmodule

