  end else if (n >= 32) begin 
  nr_wait_cycle = 1; 
  end else if (n >= 16) begin 
  nr_wait_cycle = 2; 
  end else if (n >= 8) begin 
  nr_wait_cycle = 3; 
  end else if (n >= 4) begin 
  nr_wait_cycle = 4; 
  end else if (n >= 2) begin 
  nr_wait_cycle = 5; 
  end else if (n >= 1) begin 
  nr_wait_cycle = 6; 
  end else begin 
  nr_wait_cycle = rnum[15:8]; 
  end 
 end 
 endmodule

